import { AppError } from '@pdftools/errors';

/**
 * Filenames are the interface between an untrusted string and a filesystem path, which is why they are handled
 * here and nowhere else (`docs/0-API.md` §4.5).
 *
 * Rules:
 *  - the name a user uploads is *display only* and a copy is written to `files.name`;
 *  - the name on disk is always generated by us (uuid + detected extension);
 *  - a part name coming back from the database is validated against a strict allow-list before it is joined to a
 *    path, so a poisoned row still cannot escape the output directory.
 */

const PATH_SEPARATORS = /[/\\]/g;

/**
 * Drop C0 controls and DEL.
 *
 * A code-point filter rather than a regex character class: the range `[\u0000-\u001f\u007f]` is invisible on
 * review and is what `noControlCharactersInRegex` exists to catch, whereas "keep everything from space up, drop
 * DEL" states the rule plainly. `for … of` walks code points, so a surrogate pair is never split here.
 */
function stripControlCharacters(value: string): string {
  let out = '';
  for (const character of value) {
    const code = character.codePointAt(0) ?? 0;
    if (code >= 0x20 && code !== 0x7f) out += character;
  }
  return out;
}

export function sanitizeDisplayName(name: string, maxLength = 180): string {
  const base = stripControlCharacters(name.split(PATH_SEPARATORS).pop() ?? 'file')
    .replace(/\s+/g, ' ')
    .trim();
  const cleaned = base.length > 0 ? base : 'file';
  // Truncate by code point, not by UTF-16 unit. Slicing units can cut a surrogate pair in half, and a lone
  // surrogate is not a character: it renders as a replacement glyph and makes `encodeURIComponent` throw, so a
  // long name ending in an emoji would turn its own download into a 500.
  const characters = [...cleaned];
  return characters.length > maxLength ? characters.slice(0, maxLength).join('') : cleaned;
}

/** A part name from the database or from a worker. Anything unexpected is a hard failure, not a repair. */
export function assertSafePartName(name: string): string {
  if (!/^[A-Za-z0-9._-]{1,120}$/.test(name)) {
    throw new AppError('INTERNAL_ERROR', 'The stored output name is not safe to serve.');
  }
  if (name === '.' || name === '..' || name.startsWith('.')) {
    throw new AppError('INTERNAL_ERROR', 'The stored output name is not safe to serve.');
  }
  return name;
}

/** RFC 5987-safe Content-Disposition for names that may contain non-ASCII characters. */
export function contentDisposition(name: string, type: 'attachment' | 'inline' = 'attachment'): string {
  const ascii = name.replace(/[^\x20-\x7e]/g, '_').replace(/"/g, '');
  const encoded = encodeURIComponent(name);
  return `${type}; filename="${ascii}"; filename*=UTF-8''${encoded}`;
}

/** Derive an output name from an input name: `laporan.pdf` + `-compressed` → `laporan-compressed.pdf`. */
export function deriveOutputName(inputName: string, suffix: string, ext: string): string {
  const stem = sanitizeDisplayName(inputName).replace(/\.[^.]+$/, '');
  const base = stem.length > 0 ? stem : 'document';
  const withSuffix = suffix ? `${base}${suffix}` : base;
  return `${withSuffix}${ext.startsWith('.') ? ext : `.${ext}`}`;
}
